create function pg_temp.actor343(i integer,p_aal text default'aal2')returns void language plpgsql as $$begin perform set_config('request.jwt.claim.sub','a3430000-0000-4000-8000-'||lpad(i::text,12,'0'),true);perform set_config('request.jwt.claims',jsonb_build_object('sub','a3430000-0000-4000-8000-'||lpad(i::text,12,'0'),'role','authenticated','aal',p_aal,'session_id','f3430000-0000-4000-8000-'||lpad(i::text,12,'0'))::text,true);end$$;
select ok(not has_function_privilege('anon','private.volume_reservation_read_v1(uuid)','execute')and not has_function_privilege('service_role','private.volume_reservation_read_v1(uuid)','execute'),'new read predicate grants no anonymous or service authority');
select ok(not has_table_privilege('authenticated','public.service_reservations','insert')and not has_table_privilege('authenticated','public.service_provider_allocations','insert'),'repair grants no direct reservation or allocation write');
create temporary table volume343_observed(k text primary key,v jsonb);grant all on volume343_observed to authenticated;
