select pg_temp.actor343(1);
insert into volume343_observed values('projection',to_jsonb((select count(*)from(select id,pool_id,client_organization_id,benefit_reference,reserved_units::text,consumed_units::text,released_units::text,status,expires_at from public.service_reservations where client_organization_id='b3430000-0000-4000-8000-000000000001'order by created_at desc limit 100)projected)));
