select throws_ok($$set local role authenticated;select public.activate_framework_pool('b3430000-0000-4000-8000-000000000001',null,0,168,null,null,null,'test343-no-aal2')$$,'42501','FRAMEWORK_POOL_DENIED','read repair does not bypass AAL2 for pool activation');
