insert into volume343_observed values('count-21',to_jsonb((select count(*)::integer from public.service_reservations where id::text like'd3432000%')));
reset role;
select is((select(v#>>'{}')::integer from volume343_observed where k='count-21'),0,'revoked provider session immediately loses reservation read');
set local role authenticated;
insert into volume343_observed values('count-22',to_jsonb((select count(*)::integer from public.service_provider_allocations where id::text like'd3433000%')));
reset role;
select is((select(v#>>'{}')::integer from volume343_observed where k='count-22'),0,'revoked provider session immediately loses allocation read');
set local role authenticated;
reset role;
select *from finish();
rollback;
